import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import PresetLogic from "../../web/PresetLogic.js";
import ChipProjection from "../../web/ChipProjection.js";

// Perf and behaviour guards for the chips parsing/rendering hot paths.
//
// The fixture is a synthetic library generated by tools/make_synthetic_library.py
// to mirror the shape of a real presets.json: 621 entries, 607 carrying a preset,
// the same folder taxonomy, and the same counts of bare `{group}` refs, `<tag>`s
// and `(weight)`s. Shape is what drives the engine's cost - a fixture that is
// merely "big" measures the wrong thing. The bare `{group}` refs matter most:
// each one triggers a whole-cache group scan, and they are the library's
// dominant cost.
//
// See docs/chips-parsing-bottlenecks.md for the measurements and the refactor.

const FIXTURE = fileURLToPath(
  new URL("../fixtures/presets.synthetic.json", import.meta.url)
);

const CACHE: PresetCache = JSON.parse(readFileSync(FIXTURE, "utf8"));

/**
 * Regression guards, expressed as a multiple of `calibrationMs` rather than in
 * milliseconds.
 *
 * Absolute budgets cannot hold here. `node --test` runs every test file at once
 * and the machine's other load is not ours to control: the same cold build
 * measured 1.6 ms solo and between 7 ms and 39 ms across runs of the full suite
 * - a spread wide enough that no absolute budget is both tight enough to catch a
 * regression and loose enough never to flake. Dividing by a workload that slows
 * down with the machine cancels the load out.
 *
 * Step 1+2 moved the build from ~150 ms to ~1.5 ms by dropping the per-entry
 * expansion; the memo then took the per-call cost to ~0.3 ms.
 *
 * What each budget catches, as measured:
 *
 * - `build` is a coarse guard. Its original target - the per-entry expansion
 *   coming back - is no longer catastrophic: the group and match indexes made
 *   expandRecursively ~35x cheaper, so it now reads 27.5x against this 70x
 *   budget and trips nothing. Tightening it to catch that would put it inside the
 *   spread of the candidate build (6.6-9.2x solo, 8.9x in a full-suite run,
 *   20.9x once on a cold filesystem), which is how a guard dies. What it does
 *   catch is a whole-cache operation inside a per-entry loop, and the mutation
 *   harness models that.
 * - `perCall` catches the candidate walk going back to comparing every candidate
 *   at every position: 13-17x then, ~2x now.
 * - `variantCalls` catches resolveVariantKey going back to scanning the cache:
 *   15x with the scan, 0.01x now, at the same 10 calls a render makes.
 */
const RATIO_BUDGET = {
  build: 70,
  perCall: 8,
  variantCalls: 3,
};

/**
 * A fixed CPU-bound workload, used to normalise the timings above.
 *
 * It scales with whatever CPU the process is getting, which is exactly the
 * quantity that makes an absolute budget unusable. `sink` keeps the loop from
 * being optimised away.
 */
function calibrationMs(cache: PresetCache): number {
  const keys = Object.keys(cache);
  let sink = 0;
  const start = performance.now();
  for (let pass = 0; pass < 300; pass++) {
    for (const key of keys) sink += key.length;
  }
  if (sink < 0) throw new Error("unreachable");
  return performance.now() - start;
}

/**
 * Fastest per-iteration cost of `fn`, from `runs` samples of `perSample`
 * iterations each.
 *
 * Amortising is the point. A single cold build is a ~2 ms operation, short
 * enough that one scheduler hiccup inside the timing window dominates the
 * reading - measured at 42 ms for work that takes 4 ms solo, purely from
 * running alongside every other test file. Timing a batch and dividing gives a
 * hiccup the same weight it would have in a real render, which repeats the work
 * many times over.
 */
function fastestPerCallMs(fn: () => void, runs = 5, perSample = 8): number {
  fn();
  let best = Infinity;
  for (let r = 0; r < runs; r++) {
    const start = performance.now();
    for (let k = 0; k < perSample; k++) fn();
    best = Math.min(best, (performance.now() - start) / perSample);
  }
  return best;
}

/**
 * Fastest build cost, from `runs` samples of `perSample` builds each, every
 * build on a cache object nothing has derived from yet so it pays the build
 * rather than a memo hit. The clones are made before timing starts.
 */
function fastestBuildMs(fn: (cache: PresetCache) => void, runs = 5, perSample = 8): number {
  const caches = Array.from(
    { length: runs * perSample },
    () => structuredClone(CACHE)
  );
  let next = 0;
  let best = Infinity;
  for (let r = 0; r < runs; r++) {
    const start = performance.now();
    for (let k = 0; k < perSample; k++) fn(caches[next++]);
    best = Math.min(best, (performance.now() - start) / perSample);
  }
  return best;
}

function logMeasurement(name: string, ms: number, ratio: number, budget: number): void {
  console.log(
    `    ${name.padEnd(22)} ${ms.toFixed(2).padStart(8)} ms` +
      `   ${ratio.toFixed(1).padStart(6)}x calib   budget ${budget}x`
  );
}

/** Keys carrying a preset - the entries that cost anything to index. */
function presetKeys(): string[] {
  return Object.keys(CACHE).filter((k) => CACHE[k]?.preset?.trim());
}

/** A basket of `n` realistic presets (skipping one-word entries). */
function basket(n: number): string[] {
  return presetKeys()
    .filter((k) => (CACHE[k].preset ?? "").length > 12)
    .slice(0, n);
}

/**
 * The `(group, value)` pairs the fixture's presets actually ask for - the
 * arguments a render passes to resolveVariantKey.
 */
function variantCalls(n: number): [string, string][] {
  const pairs: [string, string][] = [];
  for (const key of presetKeys()) {
    for (const match of (CACHE[key].preset ?? "").matchAll(/\{([^{}:]+):([^{}]+)\}/g)) {
      pairs.push([match[1].trim(), match[2].trim()]);
      if (pairs.length >= n) return pairs;
    }
  }
  return pairs;
}

// --- the fixture must stay representative -------------------------------

test("perf fixture keeps the shape that makes its numbers meaningful", () => {
  const keys = Object.keys(CACHE);
  const withPreset = presetKeys();

  assert.ok(
    keys.length >= 600,
    `fixture has ${keys.length} entries; the cost it tracks scales with this`
  );
  assert.ok(
    withPreset.length >= 550,
    `fixture has ${withPreset.length} presets; expected at least 550`
  );

  // Bare `{group}` refs are what trigger the whole-cache scans. If a
  // regeneration drops them the fixture goes quiet and the budgets stop biting.
  const bareVars = withPreset.reduce((total, key) => {
    const matches = (CACHE[key].preset ?? "").match(/\{[^{}:]+\}/g);
    return total + (matches ? matches.length : 0);
  }, 0);
  assert.ok(
    bareVars >= 150,
    `fixture has ${bareVars} bare {group} refs; expected at least 150`
  );

  // A folder-level config entry: the engine looks these up by folder path.
  assert.ok(
    CACHE["_/config/prepend/wear/cloth"]?.preset,
    "fixture lost the folder prepend that the wrapped-resolution test needs"
  );
});

// --- perf: the numbers the refactor is meant to move ---------------------

test("building the chip lookup stays within budget", () => {
  // Cold, on a cache nothing has derived from: this is the cost the first
  // interaction after a library load pays, and the number step 2 moved from
  // ~150 ms to ~1.5 ms by dropping the per-entry expansion.
  const keys = basket(120);
  const ms = fastestBuildMs((cache) => ChipProjection.getGroupedChips(keys, cache));
  const calibration = fastestPerCallMs(() => calibrationMs(CACHE), 5, 1);
  const ratio = ms / calibration;

  logMeasurement("lookup build (cold)", ms, ratio, RATIO_BUDGET.build);
  assert.ok(
    ratio < RATIO_BUDGET.build,
    `building the lookup cost ${ratio.toFixed(1)}x calibration (${ms.toFixed(1)} ms), budget ${RATIO_BUDGET.build}x`
  );
});

test("building the token candidates stays within budget", () => {
  const text = basket(120).join(", ");
  const ms = fastestBuildMs((cache) => PresetLogic.parseTokens(text, cache));
  const calibration = fastestPerCallMs(() => calibrationMs(CACHE), 5, 1);
  const ratio = ms / calibration;

  logMeasurement("candidate build (cold)", ms, ratio, RATIO_BUDGET.build);
  assert.ok(
    ratio < RATIO_BUDGET.build,
    `building the candidates cost ${ratio.toFixed(1)}x calibration (${ms.toFixed(1)} ms), budget ${RATIO_BUDGET.build}x`
  );
});

test("a memoised lookup stays cheap per call", () => {
  const keys = basket(120);
  const text = keys.join(", ");
  const grouped = fastestPerCallMs(() => ChipProjection.getGroupedChips(keys, CACHE));
  const parsed = fastestPerCallMs(() => PresetLogic.parseTokens(text, CACHE));
  const calibration = fastestPerCallMs(() => calibrationMs(CACHE), 5, 1);

  logMeasurement("getGroupedChips / call", grouped, grouped / calibration, RATIO_BUDGET.perCall);
  logMeasurement("parseTokens / call", parsed, parsed / calibration, RATIO_BUDGET.perCall);

  assert.ok(
    grouped / calibration < RATIO_BUDGET.perCall,
    `getGroupedChips cost ${(grouped / calibration).toFixed(1)}x calibration, budget ${RATIO_BUDGET.perCall}x`
  );
  assert.ok(
    parsed / calibration < RATIO_BUDGET.perCall,
    `parseTokens cost ${(parsed / calibration).toFixed(1)}x calibration, budget ${RATIO_BUDGET.perCall}x`
  );
});

test("resolving variant keys stays within budget", () => {
  // Both measurements matter and they catch different regressions. The per-call
  // number catches the walk coming back: a basket render makes 10 calls, and
  // each one used to scan ~550 of 620 keys, lowercasing two strings per key.
  // Measured at these same 10 calls: 0.01x calibration now, 15x with the scan.
  // The cold build catches the index itself getting expensive.
  const calls = variantCalls(10);
  assert.ok(calls.length >= 10, `fixture has too few variant refs: ${calls.length}`);
  const run = (cache: PresetCache) =>
    calls.forEach(([group, val]) => PresetLogic.resolveVariantKey(group, val, cache));

  const build = fastestBuildMs((cache) => run(cache));
  const perCall = fastestPerCallMs(() => run(CACHE), 5, 8);
  const calibration = fastestPerCallMs(() => calibrationMs(CACHE), 5, 1);

  logMeasurement("variant index build", build, build / calibration, RATIO_BUDGET.build);
  logMeasurement(
    `resolveVariantKey x${calls.length}`,
    perCall,
    perCall / calibration,
    RATIO_BUDGET.variantCalls
  );

  assert.ok(
    build / calibration < RATIO_BUDGET.build,
    `building the variant index cost ${(build / calibration).toFixed(1)}x calibration, budget ${RATIO_BUDGET.build}x`
  );
  assert.ok(
    perCall / calibration < RATIO_BUDGET.variantCalls,
    `${calls.length} resolveVariantKey calls cost ${(perCall / calibration).toFixed(1)}x calibration, budget ${RATIO_BUDGET.variantCalls}x`
  );
});

// --- behaviour the lookup must keep: the guards for step 2 ---------------
//
// Dropping the expanded lookup entries is the step most likely to change what
// resolves. These pin the three forms that actually resolve chips today.

test("every preset key in the basket resolves to its own cache entry", () => {
  const keys = basket(30);
  const chips = ChipProjection.getGroupedChips(keys, CACHE);

  assert.equal(chips.length, keys.length, "each key should produce one chip");
  chips.forEach((chip, index) => {
    assert.equal(
      chip.styleKey,
      keys[index],
      `chip ${index} resolved to ${chip.styleKey}, expected ${keys[index]}`
    );
    assert.equal(
      chip.item,
      CACHE[keys[index]],
      `chip ${index} lost its cache item`
    );
  });
});

test("a token equal to a preset's raw text resolves to that preset", () => {
  // The folder must have a prepend/append, so the wrapped entry does NOT
  // already cover the raw text - that is the case the raw-text entry serves.
  const key = presetKeys().find((k) => {
    const preset = (CACHE[k].preset ?? "").trim();
    if (!preset) return false;
    return PresetLogic.getWrappedPreset(k, preset, CACHE) !== preset;
  });
  assert.ok(key, "fixture has no preset whose folder changes its wrapped form");

  const text = (CACHE[key].preset ?? "").trim();
  const chips = ChipProjection.getGroupedChips([text], CACHE);

  assert.equal(chips.length, 1);
  assert.equal(
    (CACHE[chips[0].styleKey]?.preset ?? "").trim(),
    text,
    `"${text}" resolved to ${chips[0].styleKey}, which does not carry that text`
  );
});

test("a weighted token resolves to the underlying preset key", () => {
  // The key entry is what makes this work: a weighted token's `subArray[0]` is
  // "(key:1.5)", so without the lookup the chip would be keyed on that string.
  const key = basket(1)[0];
  const chips = ChipProjection.getGroupedChips([`(${key}:1.5)`], CACHE);

  assert.equal(chips.length, 1);
  assert.equal(
    chips[0].styleKey,
    key,
    `the weighted token should resolve to ${key}`
  );
  assert.equal(chips[0].item, CACHE[key], "the weighted chip lost its cache item");
});

test("a token equal to a wrapped preset resolves to that preset", () => {
  const key = presetKeys().find((k) => k.startsWith("wear/cloth/"));
  assert.ok(key, "fixture has no wear/cloth preset to test with");

  const preset = CACHE[key].preset ?? "";
  const wrapped = PresetLogic.getWrappedPreset(key, preset, CACHE);
  assert.notEqual(
    wrapped,
    preset.trim(),
    "the folder prepend should make the wrapped form differ from the raw preset"
  );

  const chips = ChipProjection.getGroupedChips([wrapped], CACHE);
  assert.equal(chips.length, 1);
  const resolved = chips[0].styleKey;
  assert.ok(CACHE[resolved]?.preset, `wrapped text resolved to nothing real: ${resolved}`);
  assert.equal(
    PresetLogic.getWrappedPreset(resolved, CACHE[resolved].preset ?? "", CACHE),
    wrapped,
    "the wrapped text should resolve to the entry that produced it"
  );
});

// --- the walk: what the first-character buckets must not change -----------
//
// parseTokens finds candidates through a bucket keyed on their first character
// instead of testing all ~1300 of them at every position. That is a pure
// lookup change, so these pin the three things it could break: reachability,
// order, and the word boundary.

test("every candidate the library offers is still recognised by the walk", () => {
  // A bucket keyed wrongly (lowercased, say) silently stops matching, and the
  // text degrades to plain text with no error. One probe per distinct first
  // character, using the fixture's own keys and preset texts - the strings the
  // engine is asked to match on.
  const probes = new Map<string, string>();
  for (const key of presetKeys()) {
    for (const cand of [key.trim(), (CACHE[key].preset ?? "").trim()]) {
      if (cand && !probes.has(cand[0])) probes.set(cand[0], cand);
    }
  }
  assert.ok(
    probes.size >= 15,
    `only ${probes.size} distinct first characters to probe; the fixture went quiet`
  );

  const unreachable: string[] = [];
  for (const [first, cand] of probes) {
    const tokens = PresetLogic.parseTokens(cand, CACHE);
    const covered =
      tokens.length === 1 && tokens[0].text === cand && !tokens[0].isPlainText;
    if (!covered) unreachable.push(`${JSON.stringify(first)} (${JSON.stringify(cand)})`);
  }
  assert.deepEqual(
    unreachable,
    [],
    `these candidates no longer match: ${unreachable.join(", ")}`
  );
});

test("the walk still takes the longest candidate at a position", () => {
  // The buckets partition a longest-first list, so the order inside a bucket is
  // what makes the longest match win. A bucket in any other order picks the
  // shorter candidate and splits the rest into plain text.
  const cache: PresetCache = {
    "A/Short": { preset: "red" },
    "A/Long": { preset: "red, blue" },
  };
  const tokens = PresetLogic.parseTokens("red, blue", cache);

  assert.equal(
    tokens.length,
    1,
    `expected one token, got ${JSON.stringify(tokens.map((t) => t.text))}`
  );
  assert.equal(tokens[0].key, "A/Long", "the shorter candidate won");
});

// --- the memo trap -------------------------------------------------------

test("expanding a group reference is nondeterministic without a roll manager", () => {
  // This is why memoizing expandRecursively on the cache alone is wrong: its
  // output is not stable for a fixed input, so a cached value would be the
  // previous roll's text. Any memo must key on the render generation.
  const key = Object.keys(CACHE).find((k) => {
    const preset = CACHE[k]?.preset;
    if (!preset) return false;
    const match = preset.match(/\{([^{}:]+)\}/);
    return !!match && PresetLogic.getGroupMatches(match[1], CACHE).length > 1;
  });
  assert.ok(key, "fixture has no preset referencing a multi-candidate group");

  const original = Math.random;
  let calls = 0;
  // A deterministic but varying sequence: the assertion is about the function
  // reading the roll, not about the values Math.random happens to return.
  Math.random = () => ((calls++ * 37) % 100) / 100;
  try {
    const results = new Set<string>();
    for (let i = 0; i < 8; i++) {
      results.add(PresetLogic.expandRecursively(key, CACHE));
    }
    assert.ok(
      results.size > 1,
      `expected the expansion to vary with the injected roll, got ${results.size} result(s)`
    );
  } finally {
    Math.random = original;
  }
});
